export const retry = async <T>(fn: () => Promise<T>, tries = 5): Promise<T> => {
  for (let i = 0; ; i++) { try { return await fn(); } catch (e) { if (i >= tries) throw e; await new Promise((r) => setTimeout(r, 2 ** i * 100)); } }
};

const TAX = 0.2;
export const createOrder = (items: { price: number }[]) => ({ total: items.reduce((a, i) => a + Math.round(i.price * (1 + TAX)), 0) });
export const cancelOrder = (id: string) => ({ id, status: 'cancelled' });

